describe('Task Deletion', () => {
    beforeEach(() => {
        cy.visit('/tasks'); // Adjust the URL to your application's task page
    });

    it('should delete a task when confirmed', () => {
        cy.get('.task-item').first().as('firstTask'); // Assuming tasks have a class of 'task-item'
        cy.get('@firstTask').find('.delete-button').click(); // Assuming delete button has a class of 'delete-button'

        cy.on('window:confirm', () => true); // Simulate clicking "OK" on the confirmation dialog

        cy.get('@firstTask').should('not.exist'); // Verify the task is deleted
    });

    it('should not delete a task when canceled', () => {
        cy.get('.task-item').first().as('firstTask');
        cy.get('@firstTask').find('.delete-button').click();

        cy.on('window:confirm', () => false); // Simulate clicking "Cancel" on the confirmation dialog

        cy.get('@firstTask').should('exist'); // Verify the task still exists
    });
});
